def transform(grid):
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    dominant = max(counts, key=counts.get)
    patterns = {
        1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
        2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
        3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
    }
    return [row[:] for row in patterns[dominant]]
